import csv
from collections import defaultdict

def read_rows(path):
    with open(path, newline='', encoding='utf-8-sig') as f:
        yield from csv.DictReader(f, delimiter='\t')

def cover(q, accession=None):
    rows=[r for r in read_rows(f'/root/{q}/COVERPAGE.tsv') if accession is None or r['ACCESSION_NUMBER']==accession]
    return rows

def summary(q, accession):
    return [r for r in read_rows(f'/root/{q}/SUMMARYPAGE.tsv') if r['ACCESSION_NUMBER']==accession]

def holdings(q, accession=None, cusip=None):
    for r in read_rows(f'/root/{q}/INFOTABLE.tsv'):
        if (accession is None or r['ACCESSION_NUMBER']==accession) and (cusip is None or r['CUSIP'].upper()==cusip.upper()):
            yield r

ren_q3='0001037389-25-000064'
berk_q2='0000950123-25-008343'
berk_q3='0001193125-25-282901'
print('RENAISSANCE Q3 COVER')
for r in cover('2025-q3',ren_q3): print(r)
print('RENAISSANCE Q3 SUMMARY')
for r in summary('2025-q3',ren_q3): print(r)
rh=list(holdings('2025-q3',ren_q3))
print('RENAISSANCE holding rows',len(rh),'distinct cusips',len(set(r['CUSIP'] for r in rh)))
print('sample',rh[:3])
for q,a in [('2025-q2',berk_q2),('2025-q3',berk_q3)]:
    print(f'BERKSHIRE {q} COVER')
    for r in cover(q,a): print(r)
    print('SUMMARY',summary(q,a))
    h=list(holdings(q,a))
    print('holdings rows',len(h),'distinct cusips',len(set(r['CUSIP'] for r in h)))
# Berkshire aggregate value by cusip, compare
vals={}
for q,a in [('2025-q2',berk_q2),('2025-q3',berk_q3)]:
    d=defaultdict(int)
    for r in holdings(q,a):
        if r['CUSIP']:
            try: d[r['CUSIP']]+=int(r['VALUE'])
            except (ValueError,TypeError): pass
    vals[q]=d
changes=[]
for c in set(vals['2025-q2'])|set(vals['2025-q3']):
    delta=vals['2025-q3'].get(c,0)-vals['2025-q2'].get(c,0)
    if delta>0: changes.append((delta,c,vals['2025-q2'].get(c,0),vals['2025-q3'].get(c,0)))
print('TOP BERKSHIRE POSITIVE CHANGES')
for x in sorted(changes, reverse=True)[:20]: print(x)
# Palantir q3 exact CUSIP aggregate by accession
p='69608A108'
by_acc=defaultdict(lambda: {'value':0,'shares':0,'rows':0,'issuers':set()})
for r in holdings('2025-q3',cusip=p):
    d=by_acc[r['ACCESSION_NUMBER']]
    d['value'] += int(r['VALUE']) if r['VALUE'] else 0
    d['shares'] += int(r['SSHPRNAMT']) if r['SSHPRNAMT'] else 0
    d['rows'] += 1; d['issuers'].add(r['NAMEOFISSUER'])
name_by_acc={r['ACCESSION_NUMBER']:r['FILINGMANAGER_NAME'] for r in read_rows('/root/2025-q3/COVERPAGE.tsv')}
rank=[]
for a,d in by_acc.items(): rank.append((d['value'],a,name_by_acc.get(a,''),d['shares'],d['rows'],sorted(d['issuers'])))
print('PALANTIR exact q3 accessions',len(rank),'rows',sum(x[4] for x in rank))
for x in sorted(rank, reverse=True)[:30]: print(x)
